def predict(board, action):
    mouse_row, mouse_col = action[1], action[2]
    action_char = action[0]

    # Find the mouse character on the board
    mouse_char = None
    for row in range(64):
        if board[row][mouse_col] == action_char:
            mouse_char = action_char
            break

    if mouse_char is None:
        return board  # Mouse character not found

    # Define the neighborhood of the mouse
    neighborhood = [
        (mouse_row - 1, mouse_col), (mouse_row + 1, mouse_col),
        (mouse_row, mouse_col - 1), (mouse_row, mouse_col + 1)
    ]

    # Change the mouse cell and its neighbors
    for row_delta, col_delta in neighborhood:
        if 0 <= row_delta < 64 and 0 <= col_delta < 64:
            if board[row_delta][col_delta] == mouse_char:
                board[row_delta][col_delta] = 'p' if action_char == 'MOUSE' else 'W'

    # Change the target cells to 'W'
    for row in range(64):
        if board[row][mouse_col] == mouse_char:
            board[row][mouse_col] = 'W'

    return board
